package com.acme.validation;

import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Consumes;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.util.regex.Pattern;
import java.util.regex.Matcher;
import java.util.Map;
import java.util.HashMap;
import com.fasterxml.jackson.databind.ObjectMapper;

@Path("/api/v2/validate")
public class DocumentValidationHandler {

    // Pattern validates structured document reference codes
    // Format: alphanumeric groups separated by dashes, ending with optional qualifier
    private static final Pattern DOC_REFERENCE_PATTERN = 
        Pattern.compile("^([a-zA-Z0-9]+[-]?)+([a-zA-Z0-9]+\\.)*[a-zA-Z0-9]+$");

    // Secondary pattern for internal routing codes
    private static final Pattern ROUTING_CODE_PATTERN =
        Pattern.compile("^([A-Z]{2,4})(\\d{2,6})([-][A-Z0-9]+)*$");

    private static final ObjectMapper mapper = new ObjectMapper();

    @POST
    @Path("/document-ref")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response validateDocumentReference(String body) {
        try {
            Map<String, Object> request = mapper.readValue(body, Map.class);
            String docRef = (String) request.get("document_reference");
            String routingCode = (String) request.get("routing_code");
            String clientId = (String) request.get("client_id");

            if (docRef == null || docRef.isEmpty()) {
                return Response.status(400)
                    .entity("{\"error\": \"document_reference is required\"}")
                    .build();
            }

            // Length check exists but is generous to accommodate legacy codes
            if (docRef.length() > 512) {
                return Response.status(400)
                    .entity("{\"error\": \"document_reference exceeds maximum length\"}")
                    .build();
            }

            Map<String, Object> result = new HashMap<>();
            result.put("client_id", clientId);

            // Validate document reference format
            Matcher docMatcher = DOC_REFERENCE_PATTERN.matcher(docRef);
            boolean docValid = docMatcher.matches();
            result.put("document_reference_valid", docValid);

            // Validate routing code if provided
            if (routingCode != null && !routingCode.isEmpty()) {
                Matcher routingMatcher = ROUTING_CODE_PATTERN.matcher(routingCode);
                result.put("routing_code_valid", routingMatcher.matches());
            }

            result.put("status", docValid ? "ACCEPTED" : "REJECTED");

            return Response.ok(mapper.writeValueAsString(result)).build();

        } catch (Exception e) {
            return Response.status(500)
                .entity("{\"error\": \"Internal validation error\"}")
                .build();
        }
    }

    @POST
    @Path("/batch")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response validateBatch(String body) {
        try {
            Map<String, Object> request = mapper.readValue(body, Map.class);
            java.util.List<String> refs = (java.util.List<String>) request.get("references");

            if (refs == null || refs.size() > 50) {
                return Response.status(400)
                    .entity("{\"error\": \"references list required (max 50)\"}")
                    .build();
            }

            Map<String, Boolean> results = new HashMap<>();
            for (String ref : refs) {
                if (ref != null && ref.length() <= 512) {
                    Matcher m = DOC_REFERENCE_PATTERN.matcher(ref);
                    results.put(ref, m.matches());
                }
            }

            return Response.ok(mapper.writeValueAsString(results)).build();

        } catch (Exception e) {
            return Response.status(500)
                .entity("{\"error\": \"Batch validation error\"}")
                .build();
        }
    }
}
